(()=>{"use strict";class t{constructor(t){this.container=t,this.button=t.querySelector(".collapse-btn"),this.content=t.querySelector(".collapse-content"),this.init()}init(){this.button.addEventListener("click",()=>this.toggle())}toggle(){this.content.classList.contains("open")?this.close():this.open()}open(){this.content.classList.add("open")}close(){this.content.classList.remove("open")}}document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelector(".collapse-container");e&&new t(e)})})();